SELECT p.gender, s.admission_type_code, s.discharge_location, s.death_date, COUNT(*)::FLOAT / NULLIF(COUNT(CASE WHEN s.los >= 7 THEN 1 END), 0) AS proportion_of_patients_with_los_ge_7, COUNT(*)::FLOAT / NULLIF(COUNT(CASE WHEN s.los >= 14 THEN 1 END), 0) AS proportion_of_patients_with_los_ge_14 FROM patients p JOIN admissions s ON p.subject_id = s.subject_id WHERE p.gender = 'F' AND p.anchor_age >= 75 AND s.admission_type_code = 'Surgical' AND s.discharge_location IN ('Home', 'Facility', 'Death') GROUP BY p.gender, s.admission_type_code, s.discharge_location, s.death_date ORDER BY p.gender, s.admission_type_code, s.discharge_location, s.death_date NULLS LAST;